SELECT mi1.info, n.name, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_944
WHERE (it1.id IN ('2','5','6')) AND (kt.kind IN ('episode','movie','tv series')) AND it2.id = non_leaf_944.pi_info_type_id AND it1.id = non_leaf_944.mi1_info_type_id AND (it2.id IN ('24')) AND (rt.role IN ('cinematographer','composer','editor','writer')) AND (mi1.info IN ('70 mm 6-Track','Brazil:16','Canada:PA','Canada:R','Finland:(Banned)','Germany:o.Al.','Iceland:L','Ireland:12A','Ireland:PG','Italy:VM14','New Zealand:PG','Peru:18','Philippines:G','Philippines:R-13','Portugal:M/16','Singapore:PG13','South Korea:12','Spain:7')) AND (t.production_year <= 2015) AND (t.production_year >= 1925) AND (n.name ILIKE '%fr%');